    var xhr = new XMLHttpRequest();
    xhr.open(method, url, true);
    xhr.setRequestHeader('Content-Type', 'application/json');
    xhr.timeout = 35000;

    xhr.onload = function () {
      var data;
      try { data = JSON.parse(xhr.responseText); } catch (e) { data = { error: xhr.responseText }; }
      if (xhr.status >= 200 && xhr.status < 300) {
        resolve(data);
      } else {
        reject({ status: xhr.status, data: data });
      }
    };
    xhr.onerror = function () { reject({ status: 0, data: { error: 'Network error' } }); };
    xhr.ontimeout = function () { reject({ status: 0, data: { error: 'Request timeout' } }); };
    xhr.send(body ? JSON.stringify(body) : null);
