/* ==========================================================================
 * MobileID
 * ========================================================================== */

function MobileID(options) {
  if (!options || !options.tokenUrl) {
    throw new Error('MobileID: tokenUrl is required');
  }
  this._tokenUrl = options.tokenUrl;
  this._baseUrl = (options.baseUrl || _globalBaseUrl).replace(/\/+$/, '');
  this._country = options.country || 'RU';

  this._listeners = {};
  this._sessionId = null;
  this._fingerprintHash = null;
  this._phone = null;
  this._lastPhone = null;
  this._pollAbort = null;
  this._polling = false;
  this._destroyed = false;
  this._retryCount = 0;
  this._lastEventId = 0;
  this._finalEventEmitted = false;
  this._state = 'idle';
}

MobileID.configure = function (config) {
  if (config && config.baseUrl) {
    _globalBaseUrl = config.baseUrl.replace(/\/+$/, '');
  }
};

MobileID.prototype.on = function (event, callback) {
  if (!this._listeners[event]) this._listeners[event] = [];
  this._listeners[event].push(callback);
  return this;
};

MobileID.prototype.off = function (event, callback) {
  if (!this._listeners[event]) return this;
  this._listeners[event] = this._listeners[event].filter(function (cb) { return cb !== callback; });
  return this;
};

MobileID.prototype._emit = function (event, data) {
  var callbacks = this._listeners[event];
  if (!callbacks) return;
  for (var i = 0; i < callbacks.length; i++) {
    try { callbacks[i](data); } catch (e) { console.error('MobileID event handler error:', e); }
  }
};

MobileID.prototype._emitFinal = function (event, data) {
  if (this._finalEventEmitted) return false;

  this._finalEventEmitted = true;
  this._stopPolling();
  this._state = 'final';
  this._emit(event, data);
  return true;
};

MobileID.prototype.init = function () {
  var self = this;
  this._stopPolling();
  this._sessionId = null;
  this._phone = null;
  this._destroyed = false;
  this._lastEventId = 0;
  this._finalEventEmitted = false;
  this._state = 'idle';

  return collectFingerprint()
    .then(function (fp) {
      self._fingerprintHash = fp;
      return request('POST', self._tokenUrl, { fingerprint_hash: fp });
    })
    .then(function (resp) {
      if (!resp.token) throw { status: 0, data: { error: 'No token in response from tokenUrl' } };
      return request('POST', self._baseUrl + '/api/session/init', {
        token: resp.token,
        fingerprint_hash: self._fingerprintHash
      });
    })
    .then(function (resp) {
      if (!resp.session_id) throw { status: 0, data: { error: 'No session_id in init response' } };
      self._sessionId = resp.session_id;
      self._state = 'ready';
      self._retryCount = 0;
      self._emit('ready', { session_id: resp.session_id });
    })
    .catch(function (err) {
      self._emitError('INIT_FAILED', err);
      throw err;
    });
};

MobileID.prototype.start = function (phone) {
  var self = this;
  if (!this._sessionId) return Promise.reject(new Error('MobileID: call init() first'));

  var result = normalizePhone(phone, this._country);
  if (result.error) {
    this._emit('error', { code: 'INVALID_PHONE', message: result.error });
    return Promise.reject(new Error(result.error));
  }

  this._phone = result.phone;
  this._lastPhone = result.phone;

  return request('POST', this._baseUrl + '/api/session/' + this._sessionId + '/start', {
    phone: this._phone,
    fingerprint_hash: this._fingerprintHash
  })
    .then(function (resp) {
      if (resp.error === 'rate limit exceeded') {
        self._emit('rate_limit', {});
        return;
      }

      var status = resp.status || 'pending';
      self._retryCount = 0;

      // Во всех случаях (в т.ч. синхронизированный статус) эмитим pending
      // и запускаем polling — он вернёт актуальные события немедленно.
      switch (status) {
        case 'otp_required': self._state = 'otp'; break;
        case 'verified':
        case 'rejected':    self._state = 'final'; break;
        default:            self._state = 'pending'; break;
      }
      self._emit('pending', { phone: self._phone });
      self._startPolling();
    })
    .catch(function (err) {
      if (err && err.data && err.data.error === 'rate limit exceeded') {
        self._emit('rate_limit', {});
        return;
      }
      self._emitError('START_FAILED', err);
      throw err;
    });
};

MobileID.prototype.submitOTP = function (code) {
  var self = this;
  if (!this._sessionId) return Promise.reject(new Error('MobileID: no active session'));

  return request('POST', this._baseUrl + '/api/session/' + this._sessionId + '/otp', {
    code: code,
    fingerprint_hash: this._fingerprintHash
  })
    .then(function (resp) {
      switch (resp.status) {
        case 'verified':
          self._emitFinal('verified', {
            verify_token: resp.event && resp.event.data ? resp.event.data.verify_token : null
          });
          break;
        case 'invalid_code':
          self._emit('invalid_code', { message: resp.message || 'Invalid code' });
          break;
        case 'session_expired':
          self._emitFinal('expired', {
            verify_token: resp.event && resp.event.data ? resp.event.data.verify_token : null
          });
          break;
      }
    })
    .catch(function (err) {
      self._emitError('OTP_FAILED', err);
      throw err;
    });
};

MobileID.prototype.silentRetry = function () {
  var self = this;
  this._retryCount++;
  var phone = this._lastPhone;

  return this.init()
    .then(function () {
      if (phone) return self.start(phone);
    })
    .catch(function () {
      // Ошибки уже обработаны через события
    });
};

MobileID.prototype.normalizePhone = function (phone, country) {
  return normalizePhone(phone, country || this._country);
};

MobileID.prototype.getPhone = function () { return this._phone; };
MobileID.prototype.getSessionId = function () { return this._sessionId; };
MobileID.prototype.getFingerprintHash = function () { return this._fingerprintHash; };
MobileID.prototype.getState = function () { return this._state; };
MobileID.prototype.getRetryCount = function () { return this._retryCount; };

MobileID.prototype.destroy = function () {
  this._destroyed = true;
  this._stopPolling();
  this._sessionId = null;
  this._phone = null;
  this._fingerprintHash = null;
  this._listeners = {};
  this._state = 'idle';
};

MobileID.prototype._startPolling = function () {
  this._stopPolling();
  this._poll();
};

MobileID.prototype._stopPolling = function () {
  this._polling = false;
  if (this._pollAbort) this._pollAbort.abort = true;
};

MobileID.prototype._poll = function () {
  if (this._destroyed || !this._sessionId) return;
  var self = this;
  this._polling = true;

  var abort = { abort: false };
  this._pollAbort = abort;

  var url = this._baseUrl
    + '/api/session/' + this._sessionId
    + '/events?last_event_id=' + this._lastEventId
    + '&fingerprint_hash=' + encodeURIComponent(this._fingerprintHash);

  request('GET', url)
    .then(function (resp) {
      if (abort.abort || self._destroyed) return;
      var events = resp.events || [];
      for (var i = 0; i < events.length; i++) {
        var ev = events[i];
        if (ev.id > self._lastEventId) self._lastEventId = ev.id;
        self._handleEvent(ev);
      }
      if (self._polling && !self._destroyed) self._poll();
    })
    .catch(function (err) {
      if (abort.abort || self._destroyed) return;
      self._stopPolling();
      self._emitError('POLLING_ERROR', err);
    });
};

MobileID.prototype._handleEvent = function (ev) {
  switch (ev.type) {
    case 'otp_required':
      this._state = 'otp';
      this._retryCount = 0;
      this._emit('otp_required', {});
      break;
    case 'verified':
      this._emitFinal('verified', { verify_token: ev.data ? ev.data.verify_token : null });
      break;
    case 'rejected':
      this._emitFinal('rejected', { verify_token: ev.data ? ev.data.verify_token : null });
      break;
    case 'session_expired':
      this._emitFinal('expired', { verify_token: ev.data ? ev.data.verify_token : null });
      break;
    default:
      this._stopPolling();
      this.silentRetry();
      break;
  }
};

MobileID.prototype._emitError = function (code, err) {
  var message = 'Unknown error';
  if (err && err.data && err.data.error) message = err.data.error;
  else if (err && err.message) message = err.message;
  this._emit('error', { code: code, message: message, status: err ? err.status : 0 });
};

MobileID.countries = function () {
  return Object.keys(PHONE_RULES).map(function (key) {
    var rule = PHONE_RULES[key];
    return { code: rule.code, prefix: rule.prefix, length: rule.length };
  });
};

MobileID.normalizePhone = normalizePhone;

